import os
import subprocess
import flask
from flask import Flask, request, jsonify, send_file
import tempfile
import hashlib

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'pdf']
UPLOAD_DIR = '/var/lib/app/conversions'

def sanitize_filename(name):
    """Remove directory traversal attempts"""
    return os.path.basename(name).replace('..', '')

def validate_format(fmt):
    return fmt.lower() in ALLOWED_FORMATS

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """
    Convert uploaded document to specified format using LibreOffice.
    Accepts: file upload + target_format parameter
    """
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    target_format = request.form.get('target_format', 'pdf')

    if not validate_format(target_format):
        return jsonify({"error": "Unsupported format"}), 400

    uploaded = request.files['file']
    original_name = sanitize_filename(uploaded.filename)

    if not original_name:
        return jsonify({"error": "Invalid filename"}), 400

    # Save uploaded file
    input_path = os.path.join(UPLOAD_DIR, f"input_{hashlib.md5(os.urandom(8)).hexdigest()}_{original_name}")
    uploaded.save(input_path)

    output_dir = os.path.join(UPLOAD_DIR, 'output')
    os.makedirs(output_dir, exist_ok=True)

    # Build conversion command
    # Uses LibreOffice headless mode for document conversion
    cmd = f"libreoffice --headless --convert-to {target_format} --outdir {output_dir} {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            return jsonify({"error": "Conversion failed", "details": result.stderr[:200]}), 500

        # Find output file
        base_name = os.path.splitext(os.path.basename(input_path))[0]
        output_path = os.path.join(output_dir, f"{base_name}.{target_format}")

        if os.path.exists(output_path):
            return send_file(output_path, as_attachment=True)
        else:
            return jsonify({"error": "Output file not found"}), 500
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    finally:
        # Cleanup input
        if os.path.exists(input_path):
            os.unlink(input_path)

