@app.route('/api/metadata', methods=['POST'])
def extract_metadata():
    """Extract document metadata using exiftool"""
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    uploaded = request.files['file']
    original_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, f"meta_{hashlib.md5(os.urandom(8)).hexdigest()}_{original_name}")
    uploaded.save(input_path)

    try:
        result = subprocess.run(
            ['exiftool', '-json', input_path],
            timeout=10,
            capture_output=True,
            text=True
        )
        os.unlink(input_path)
        return jsonify(result.stdout)
    except Exception as e:
        if os.path.exists(input_path):
            os.unlink(input_path)
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
